function wsExportRoot(paths, scope) {
  const list = (paths || []).filter(Boolean).map(String);
  if (!list.length)
    return "";
  let acc = list[0].split("/").slice(0, -1);
  for (const p of list) {
    const bits = p.split("/").slice(0, -1);
    let i = 0;
    while (i < acc.length && i < bits.length && acc[i] === bits[i])
      i++;
    acc = acc.slice(0, i);
    if (!acc.length)
      return "";
  }
  const root = acc.join("/");
  if (root && scope && String(scope) === root) {
    return acc.slice(0, -1).join("/");
  }
  return root;
}
function wsDemoteHeadings(md, by) {
  const n = Math.max(0, Math.floor(Number(by) || 0));
  if (!n)
    return String(md == null ? "" : md);
  let fence = null;
  return String(md == null ? "" : md).split("\n").map((line) => {
    const f = /^\s*(```+|~~~+)/.exec(line);
    if (f) {
      if (!fence)
        fence = f[1][0];
      else if (f[1][0] === fence)
        fence = null;
      return line;
    }
    if (fence)
      return line;
    const h = /^(#{1,6})(\s)/.exec(line);
    if (!h)
      return line;
    const want = Math.min(6, h[1].length + n);
    return "#".repeat(want) + line.slice(h[1].length);
  }).join("\n");
}
function wsHostTint() {
  try {
    const v = getComputedStyle(document.body).getPropertyValue("--background-secondary");
    if (v && v.trim())
      return v.trim();
  } catch (_) {
    wsCatch("wsHostTint: const v = getComputedStyle(document.body)", _);
  }
  return "#ececec";
}
function wsFileHeadLevel(o, sec) {
  if (!o || !o.folderHeadings)
    return 2;
  return Math.min(6, (sec && sec.depth || 0) + 1);
}
function wsSecHeadLevel(o, sec) {
  if (!o || !o.folderHeadings)
    return 2;
  if (sec && sec.folder)
    return Math.min(6, sec.depth || 1);
  return wsFileHeadLevel(o, sec);
}
function wsDeepestLevel(o, sections) {
  let d = 1;
  for (const sec of sections || [])
    d = Math.max(d, wsSecHeadLevel(o, sec));
  return d;
}
function wsTocSteps(o, sections) {
  let top = 6;
  for (const sec of sections || [])
    top = Math.min(top, wsSecHeadLevel(o, sec));
  return (sec) => Math.max(0, wsSecHeadLevel(o, sec) - top);
}
