  renderFlagCount(st) {
    st.addDropdown((d) => {
      d.addOption("0", "None");
      for (let i = 1; i <= WS_STATE_IDS.length; i++)
        d.addOption(String(i), i === 1 ? "1 flag" : i + " flags");
      d.setValue(String(this.plugin.flagCount()));
      d.onChange((v) => {
        void (async () => {
          this.plugin.settings.flagCount = Number(v);
          await this.plugin.saveSettings();
          this.update();
        })();
      });
    });
  }
  flagRows(visible) {
    const plugin = this.plugin;
    const count = plugin.flagCount();
    const defs = plugin.flagDefs();
    const rows = [];
    for (let i = 0; i < count; i++) {
      const f = defs[i];
      rows.push(rendered({
        name: "Flag " + (i + 1),
        desc: "",
        visible,
        searchable: false,
        render: (st) => {
          st.settingEl.addClass("ws-flagrow");
          const icon = st.controlEl.createSpan({ cls: "ws-flagrow-icon" });
          wsSvgInto(icon, wsFlagSvg(f.id, 13));
          const write = async (patch) => {
            const all2 = plugin.flagDefs().map((x) => Object.assign({}, x));
            Object.assign(all2.filter((x) => x.id === f.id)[0], patch);
            plugin.settings.flags = all2;
            await plugin.saveSettings();
          };
          st.addText((t) => t.setPlaceholder(f.id).setValue(f.label).onChange((v) => {
            void write({ label: String(v || "").trim() || f.id });
          }));
          st.addDropdown((d) => {
            for (const sh of WS_FLAG_SHAPES)
              d.addOption(sh.id, sh.label);
            d.setValue(f.shape);
            d.onChange((v) => {
              void (async () => {
                await write({ shape: v });
                this.update();
              })();
            });
          });
          this.swatchRow(st);
          st.addColorPicker((cp) => cp.setValue(f.light).onChange((v) => {
            void write({ light: v });
          }));
          st.addColorPicker((cp) => cp.setValue(f.dark).onChange((v) => {
            void write({ dark: v });
          }));
        }
      }, ["flags"]));
    }
    return rows;
  }
