  renderSettingsText(st) {
    const plugin = this.plugin;
    st.addButton((b) => b.setButtonText("Copy").onClick(() => {
      void (async () => {
        try {
          await navigator.clipboard.writeText(plugin.settingsCopyText());
          new import_obsidian2.Notice("Word-Smith: settings copied.", 4e3);
        } catch {
          new import_obsidian2.Notice("Word-Smith: could not reach the clipboard.", 6e3);
        }
      })();
    }));
    st.addButton((b) => b.setButtonText("Paste").onClick(() => {
      void (async () => {
        let text = "";
        try {
          text = await navigator.clipboard.readText();
        } catch {
          new import_obsidian2.Notice("Word-Smith: could not read the clipboard.", 6e3);
          return;
        }
        const r = await plugin.settingsPasteText(text);
        if (r.error !== void 0) {
          new import_obsidian2.Notice("Word-Smith: " + r.error, 8e3);
          return;
        }
        new import_obsidian2.Notice("Word-Smith: " + r.applied + " setting" + (r.applied === 1 ? "" : "s") + " pasted" + (r.repaired.length ? ", " + r.repaired.length + " reset to the default (" + r.repaired.join(", ") + ")" : "") + ". Undo is beside this button.", 8e3);
        this.update();
      })();
    }));
    st.addButton((b) => b.setButtonText("Undo").setDisabled(!plugin._settingsUndo).onClick(() => {
      void (async () => {
        const r = await plugin.settingsUndoPaste();
        new import_obsidian2.Notice("Word-Smith: " + (r.error || "the previous settings are back."), 6e3);
        this.update();
      })();
    }));
  }
